using System.IO;using System.IO.Compression;using System.Text;using System.Text.Json;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using Spectra.Installer;
class Inline(Action<SetupProgress> action):IProgress<SetupProgress>{public void Report(SetupProgress value)=>action(value);}
class Program{
 static MemoryStream Package(params (string Name,string Text)[] files){var s=new MemoryStream();using(var z=new ZipArchive(s,ZipArchiveMode.Create,true))foreach(var f in files){using var writer=new StreamWriter(z.CreateEntry(f.Name).Open());writer.Write(f.Text);}s.Position=0;return s;}
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 [STAThread]static void Main(string[] args){SetupText.Validate();var folder=Path.Combine(Path.GetTempPath(),"SpectraInstallerTests",Guid.NewGuid().ToString("N"));var target=Path.Combine(folder,"Spectra");Directory.CreateDirectory(target);File.WriteAllText(Path.Combine(target,"Spectra.exe"),"old");File.WriteAllText(Path.Combine(target,"user-settings.json"),"keep");
 try{
  using(var zip=Package(("Spectra.exe","new"),("Web/a.txt","asset")))InstallEngine.Install(zip,target,"uk",new Inline(_=>{}),default);
  Check(File.ReadAllText(Path.Combine(target,"Spectra.exe"))=="new","install output");Check(File.ReadAllText(Path.Combine(target,"user-settings.json"))=="keep","user data preserved");using(var pref=JsonDocument.Parse(File.ReadAllText(Path.Combine(target,"install-preferences.json"))))Check(pref.RootElement.GetProperty("language").GetString()=="uk","launcher language");
  using(var zip=Package(("../escape","bad"),("Spectra.exe","bad"))){try{InstallEngine.Install(zip,target,"ru",new Inline(_=>{}),default);throw new Exception("Traversal accepted");}catch(IOException){}}Check(!File.Exists(Path.Combine(folder,"escape")),"archive contained");
  using(var token=new CancellationTokenSource()){token.Cancel();using var zip=Package(("Spectra.exe","cancelled"));try{InstallEngine.Install(zip,target,"en",new Inline(_=>{}),token.Token);throw new Exception("Cancellation ignored");}catch(OperationCanceledException){}}Check(File.ReadAllText(Path.Combine(target,"Spectra.exe"))=="new","cancel preserves files");
  File.WriteAllText(Path.Combine(target,"locked.txt"),"locked");using(var locked=new FileStream(Path.Combine(target,"locked.txt"),FileMode.Open,FileAccess.ReadWrite,FileShare.None)){using var zip=Package(("Spectra.exe","replacement"),("locked.txt","replace"));try{InstallEngine.Install(zip,target,"en",new Inline(_=>{}),default);throw new Exception("Locked replacement accepted");}catch(IOException){}}Check(File.ReadAllText(Path.Combine(target,"Spectra.exe"))=="new","rollback restores prior file");
  Console.WriteLine("PASS installer: 19 complete locales, safe paths, installation, preserved user files, language handoff, cancellation and rollback");
  if(args.Contains("--github")){using var package=GithubUpdate.Prepare(target,new Inline(p=>Console.WriteLine(p.Phase+" "+p.File)),default).GetAwaiter().GetResult();using var zip=ZipFile.OpenRead(package.File);Check(zip.GetEntry("Spectra.exe")!=null,"GitHub package missing executable");Console.WriteLine("PASS live forced stable update prepared from GitHub: "+package.Version);}
  var app=new Application();var window=new MainWindow();var content=(FrameworkElement)window.Content;content.Width=980;content.Height=700;
  void Render(string name){content.Measure(new Size(980,700));content.Arrange(new Rect(0,0,980,700));content.UpdateLayout();System.Windows.Threading.Dispatcher.CurrentDispatcher.Invoke(()=>{},System.Windows.Threading.DispatcherPriority.ApplicationIdle);var image=new RenderTargetBitmap(980,700,96,96,PixelFormats.Pbgra32);image.Render(content);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));Directory.CreateDirectory("test-results");using var file=File.Create("test-results/"+name+".png");encoder.Save(file);}
  Render("installer-welcome");var language=(ComboBox)window.FindName("LanguagePicker");foreach(var code in SetupText.Languages.Keys){language.SelectedValue=code;content.Measure(new Size(980,700));content.Arrange(new Rect(0,0,980,700));}language.SelectedValue="ru";
  ((Button)window.FindName("Next")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Render("installer-options");((Button)window.FindName("Next")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Render("installer-review");var folderBox=(TextBox)window.FindName("Folder");folderBox.Text=target;var existing=(FrameworkElement)window.FindName("ExistingPanel");Check(existing.Visibility==Visibility.Visible,"custom installed path detected");var update=(Button)window.FindName("UpdateButton");update.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(((TextBlock)window.FindName("Description")).Text.Contains("MineShprot1/Spectra"),"force stable update confirmation");
  var link=Path.Combine(folder,"test.lnk");typeof(MainWindow).GetMethod("Shortcut",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static)!.Invoke(null,new object[]{link,Path.Combine(target,"Spectra.exe")});Check(File.Exists(link),"Windows shortcut generated");
  Console.WriteLine("PASS native installer layout and navigation for all 19 languages");
 }finally{var full=Path.GetFullPath(folder);if(full.StartsWith(Path.GetFullPath(Path.Combine(Path.GetTempPath(),"SpectraInstallerTests"))+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))Directory.Delete(full,true);}}
}